"use client";

import styles from "./studio.module.css";

interface FloatingCardIconProps {
    src: string;
    alt: string;
    /** 0 | 1 | 2 — controls animation phase offset */
    index: number;
}

export function FloatingCardIcon({ src, alt, index }: FloatingCardIconProps) {
    return (
        <div className={styles.floatingIconWrap} data-float-index={String(index)}>
            <img src={src} alt={alt} className={styles.floatingIconImg} />
            <span className={styles.floatingIconShadow} aria-hidden="true" />
        </div>
    );
}
