"use client";

import Link from "next/link";
import * as React from "react";
import { BookImage, Eraser, CheckCircle2 } from "lucide-react";
import { FloatingCardIcon } from "./floating-card-icon";
import { PendingAsset } from "./pending-asset";
import { BRAND_LOGO_PATH, HOME_CARDS } from "./studio-data";
import styles from "./studio.module.css";

const HANDOFF_STORAGE_KEY = "studio:pending-media-handoff";
const STUDIO_PANELS_STORAGE_KEY = "studio:persisted-panels:v1";
const STUDIO_OUTPUTS_STORAGE_KEY = "studio:persisted-outputs:v1";
const STUDIO_CLEAR_SIGNAL_KEY = "studio:clear-signal:v1";

export default function LandingPage() {
    const [showClearDialog, setShowClearDialog] = React.useState(false);
    const [showSuccess, setShowSuccess] = React.useState(false);

    React.useEffect(() => {
        if (!showSuccess) {
            return;
        }

        const timer = window.setTimeout(() => {
            setShowSuccess(false);
        }, 2200);

        return () => {
            window.clearTimeout(timer);
        };
    }, [showSuccess]);

    const handleConfirmClear = () => {
        window.sessionStorage.removeItem(HANDOFF_STORAGE_KEY);
        window.sessionStorage.removeItem(STUDIO_PANELS_STORAGE_KEY);
        window.sessionStorage.removeItem(STUDIO_OUTPUTS_STORAGE_KEY);
        window.sessionStorage.setItem(STUDIO_CLEAR_SIGNAL_KEY, String(Date.now()));
        setShowClearDialog(false);
        setShowSuccess(true);
    };

    return (
        <main className={styles.landingPage}>
            <div className={styles.landingBackdrop} />
            <div className={styles.landingCircles} aria-hidden="true">
                <span />
                <span />
                <span />
                <span />
            </div>

            <header className={styles.landingHeader}>
                <div />
                <div className={styles.brandLockup}>
                    <PendingAsset
                        src={BRAND_LOGO_PATH}
                        alt="飞思玖·璇玑AI"
                        className={styles.brandLogoAsset}
                        imageClassName={styles.brandLogoImage}
                        fallbackLabel="AI"
                    />
                </div>
            </header>

            {showSuccess ? (
                <div className={styles.successToast} role="status" aria-live="polite">
                    <CheckCircle2 size={20} />
                    <span>清除成功</span>
                </div>
            ) : null}

            <section className={styles.heroSection}>
                <h1 className={styles.heroTitle}>让想法 造出来</h1>
                <p className={styles.heroSubtitle}>Let Ideas Take Shape</p>
                <Link href="/portfolio" className={styles.albumButton}>
                    <img src="/images/收藏书籍.png" alt="" className={styles.buttonIconAsset} aria-hidden="true" />
                    <span>作品册</span>
                </Link>

                <div className={styles.homeCardGrid}>
                    {HOME_CARDS.map((card, idx) => (
                        <Link
                            key={card.id}
                            href={card.href}
                            className={styles.homeCard}
                            data-card-theme={card.themeClassName}
                        >
                            <FloatingCardIcon src={card.assetPath} alt={card.title} index={idx} />
                            <strong>{card.title}</strong>
                            <span>{card.subtitle}</span>
                        </Link>
                    ))}
                </div>
            </section>

            <button
                className={styles.floatingAction}
                type="button"
                aria-label="清理数据"
                onClick={() => setShowClearDialog(true)}
            >
                <img src="/images/clear.png" alt="" className={styles.buttonIconAsset} aria-hidden="true" />
            </button>

            {showClearDialog ? (
                <div
                    className={styles.dialogBackdrop}
                    role="presentation"
                    onClick={(event) => {
                        if (event.target === event.currentTarget) {
                            setShowClearDialog(false);
                        }
                    }}
                >
                    <div
                        className={styles.confirmDialog}
                        role="dialog"
                        aria-modal="true"
                        aria-label="确认清除数据"
                    >
                        <div className={styles.confirmDialogIconWrap}>
                            <img src="/images/清除数据.png" alt="" className={styles.confirmDialogIcon} aria-hidden="true" />
                        </div>
                        <h2>确定要清除数据吗？</h2>
                        <p>确认清除后，会清空所有信息和作品</p>
                        <div className={styles.confirmDialogActions}>
                            <button
                                className={styles.clearDialogCancelBtn}
                                type="button"
                                onClick={() => setShowClearDialog(false)}
                            >
                                取消
                            </button>
                            <button
                                className={styles.clearDialogConfirmBtn}
                                type="button"
                                onClick={handleConfirmClear}
                            >
                                清除
                            </button>
                        </div>
                    </div>
                </div>
            ) : null}
        </main>
    );
}
